package ro.leo.visual;
import java.io.*;import java.util.*;import java.util.zip.*;import java.security.*;import org.json.*;
/** Strict local release ZIP. Payload scripts are hashed and discarded, never executed. */
final class AppBundle {
 static final String[] FILES={"leo-keypad-ime.apk","leo-visual.apk","install-app-bundle.py","README.txt"};
 static String hex(byte[] value){StringBuilder b=new StringBuilder();for(byte n:value)b.append(String.format(Locale.ROOT,"%02x",n&255));return b.toString();}
 static String digest(File f)throws Exception{MessageDigest sha=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)sha.update(b,0,n);}return hex(sha.digest());}
 static JSONObject unpack(File input,File output)throws Exception{
  if(!input.isFile()||input.length()>67108864||!output.isDirectory())throw new IOException("Arhivă indisponibilă sau peste 64 MiB");
  try(ZipFile zip=new ZipFile(input)){String prefix=null;Set<String> entries=new HashSet<String>();Enumeration<? extends ZipEntry> all=zip.entries();while(all.hasMoreElements()){ZipEntry e=all.nextElement();String name=e.getName();if(name.contains("\\")||name.startsWith("/")||Arrays.asList(name.split("/")).contains("..")||!entries.add(name)||entries.size()>6)throw new IOException("Structură ZIP invalidă");int slash=name.indexOf('/');if(slash<=0)throw new IOException("Pachet fără director de versiune");String folder=name.substring(0,slash+1);if(prefix==null)prefix=folder;else if(!prefix.equals(folder))throw new IOException();if(e.isDirectory()&&!name.equals(folder))throw new IOException();}if(prefix==null)throw new IOException();Set<String> expected=new HashSet<String>();expected.add(prefix+"manifest.json");for(String file:FILES)expected.add(prefix+file);entries.remove(prefix);if(!entries.equals(expected))throw new IOException("Fișiere neașteptate în pachet");
   ZipEntry manifest=zip.getEntry(prefix+"manifest.json");JSONObject data;try(InputStream in=zip.getInputStream(manifest)){data=new JSONObject(new String(BookDocument.bytes(in,262144),"UTF-8"));}Object versionCode=data.get("version_code");if(!(versionCode instanceof Integer||versionCode instanceof Long)||((Number)versionCode).longValue()>Integer.MAX_VALUE)throw new IOException("Cod versiune invalid");if(!data.optString("format").equals("leo-app-bundle")||data.optInt("schema")!=1||!data.getString("version").matches("[0-9]+\\.[0-9]+\\.[0-9]+(?:-[a-z0-9.-]+)?")||data.getInt("version_code")<1)throw new IOException("Manifest Leo invalid");JSONObject files=data.getJSONObject("files");Set<String> keys=new HashSet<String>();for(Iterator<String> it=files.keys();it.hasNext();)keys.add(it.next());if(!keys.equals(new HashSet<String>(Arrays.asList(FILES))))throw new IOException();
   for(String name:FILES){JSONObject info=files.getJSONObject(name);long size=info.getLong("bytes"),limit=name.endsWith(".apk")?33554432:524288;if(size<1||size>limit||!info.getString("sha256").matches("[a-f0-9]{64}"))throw new IOException("Limită pachet depășită");MessageDigest hash=MessageDigest.getInstance("SHA-256");File destination=name.endsWith(".apk")?new File(output,name):null;try(InputStream in=zip.getInputStream(zip.getEntry(prefix+name));OutputStream out=destination==null?new OutputStream(){public void write(int n){}}:new FileOutputStream(destination)){byte[] b=new byte[65536];long count=0;int n;while((n=in.read(b))!=-1){count+=n;if(count>size||count>limit)throw new IOException("Mărime incorectă");hash.update(b,0,n);if(destination!=null)out.write(b,0,n);}if(count!=size||!hex(hash.digest()).equals(info.getString("sha256")))throw new IOException("SHA-256 incorect");}}
   try(FileOutputStream out=new FileOutputStream(new File(output,"manifest.json"))){out.write(data.toString().getBytes("UTF-8"));out.getFD().sync();}return data;
  }
 }
}
